 1→import type { Config } from './config.js'
 2→import type { AgentDefinition } from './types.js'
 3→import { AgentInstance } from './agent-instance.js'
 4→
 5→export class AgentManager {
 6→  constructor(private config: Config) {}
 7→
 8→  getAvailableAgents(): AgentDefinition[] {
 9→    return Object.entries(this.config.agents).map(([name, cfg]) => ({
10→      name,
11→      command: cfg.command,
12→      args: cfg.args,
13→      workingDirectory: cfg.workingDirectory,
14→      env: cfg.env,
15→    }))
16→  }
17→
18→  getAgent(name: string): AgentDefinition | undefined {
19→    const cfg = this.config.agents[name]
20→    if (!cfg) return undefined
21→    return { name, ...cfg }
22→  }
23→
24→  async spawn(agentName: string, workingDirectory: string): Promise<AgentInstance> {
25→    const agentDef = this.getAgent(agentName)
26→    if (!agentDef) throw new Error(`Agent "${agentName}" not found in config`)
27→    return AgentInstance.spawn(agentDef, workingDirectory)
28→  }
29→}
