    default: '60',
    validate: (val) => {
      const n = Number(val)
      return (!isNaN(n) && Number.isInteger(n) && n > 0) || 'Must be a positive integer'
    },
  })

  return {
    allowedUserIds,
    maxConcurrentSessions: Number(maxConcurrentStr),
    sessionTimeoutMinutes: Number(timeoutStr),
  }
}
