import type { ConfigManager } from './config.js'

function printWelcomeBanner(): void {
  console.log(`
┌──────────────────────────────────────┐
│                                      │
│   Welcome to OpenACP!                │
│                                      │
│   Let's set up your configuration.   │
│                                      │
└──────────────────────────────────────┘
`)
