    const action = await select({
      message: 'What would you like to do?',
      choices: [
        { name: 'Re-enter token', value: 'retry' },
        { name: 'Skip validation (use token as-is)', value: 'skip' },
      ],
    })
    if (action === 'skip') break
  }

  let chatId = 0
