    chatId = Number(chatIdStr.trim())

    console.log('Validating chat ID...')
    const result = await validateChatId(botToken, chatId)
    if (result.ok) {
      groupTitle = result.title
      if (!result.isForum) {
        console.log(`⚠ Warning: "${result.title}" does not have Topics enabled.`)
