 92→
 93→    // 5. Validate with Zod
 94→    const result = ConfigSchema.safeParse(raw)
 95→    if (!result.success) {
 96→      log.error('Config validation failed:')
 97→      for (const issue of result.error.issues) {
 98→        log.error(`  ${issue.path.join('.')}: ${issue.message}`)
 99→      }
100→      process.exit(1)
101→    }
102→    this.config = result.data
103→  }
104→
105→  get(): Config {
106→    return this.config
107→  }
108→
109→  async save(updates: Record<string, unknown>): Promise<void> {
110→    // Read current file, merge updates, write back
111→    const raw = JSON.parse(fs.readFileSync(this.configPath, 'utf-8'))
112→    this.deepMerge(raw, updates)
113→    fs.writeFileSync(this.configPath, JSON.stringify(raw, null, 2))
114→    // Re-validate and update in-memory config
115→    const result = ConfigSchema.safeParse(raw)
116→    if (result.success) {
117→      this.config = result.data
118→    }
119→  }
120→
121→  resolveWorkspace(input?: string): string {
122→    if (!input) {
123→      const resolved = expandHome(this.config.workspace.baseDir)
124→      fs.mkdirSync(resolved, { recursive: true })
125→      return resolved
126→    }
127→    if (input.startsWith('/') || input.startsWith('~')) {
128→      const resolved = expandHome(input)
129→      fs.mkdirSync(resolved, { recursive: true })
130→      return resolved
131→    }
132→    // Named workspace → lowercase, under baseDir
133→    const name = input.toLowerCase()
134→    const resolved = path.join(expandHome(this.config.workspace.baseDir), name)
135→    fs.mkdirSync(resolved, { recursive: true })
136→    return resolved
137→  }
138→
139→  async exists(): Promise<boolean> {
140→    return fs.existsSync(this.configPath)
141→  }
142→
143→  getConfigPath(): string {
144→    return this.configPath
145→  }
146→
147→  async writeNew(config: Config): Promise<void> {
148→    const dir = path.dirname(this.configPath)
149→    fs.mkdirSync(dir, { recursive: true })
150→    fs.writeFileSync(this.configPath, JSON.stringify(config, null, 2))
151→  }
152→
153→  private applyEnvOverrides(raw: Record<string, unknown>): void {
154→    const overrides: [string, string[]][] = [
155→      ['OPENACP_TELEGRAM_BOT_TOKEN', ['channels', 'telegram', 'botToken']],
156→      ['OPENACP_TELEGRAM_CHAT_ID', ['channels', 'telegram', 'chatId']],
157→      ['OPENACP_DEFAULT_AGENT', ['defaultAgent']],
158→    ]
159→    for (const [envVar, configPath] of overrides) {
160→      const value = process.env[envVar]
161→      if (value !== undefined) {
162→        let target = raw as Record<string, any>
163→        for (let i = 0; i < configPath.length - 1; i++) {
164→          if (!target[configPath[i]]) target[configPath[i]] = {}
165→          target = target[configPath[i]]
166→        }
167→        const key = configPath[configPath.length - 1]
168→        // Convert chatId to number
169→        target[key] = key === 'chatId' ? Number(value) : value
170→      }
171→    }
172→  }
173→
174→  private deepMerge(target: Record<string, any>, source: Record<string, any>): void {
175→    for (const key of Object.keys(source)) {
176→      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
177→        if (!target[key]) target[key] = {}
178→        this.deepMerge(target[key], source[key])
179→      } else {
180→        target[key] = source[key]
181→      }
182→    }
183→  }
