  1→import { execFileSync } from 'node:child_process'
  2→import { input, confirm, select, checkbox } from '@inquirer/prompts'
  3→import type { Config, ConfigManager } from './config.js'
  4→
  5→// --- Telegram validation ---
  6→
  7→export async function validateBotToken(token: string): Promise<
  8→  { ok: true; botName: string; botUsername: string } | { ok: false; error: string }
  9→> {
 10→  try {
 11→    const res = await fetch(`https://api.telegram.org/bot${token}/getMe`)
 12→    const data = await res.json() as { ok: boolean; result?: { first_name: string; username: string }; description?: string }
 13→    if (data.ok && data.result) {
 14→      return { ok: true, botName: data.result.first_name, botUsername: data.result.username }
 15→    }
 16→    return { ok: false, error: data.description || 'Invalid token' }
 17→  } catch (err) {
 18→    return { ok: false, error: (err as Error).message }
 19→  }
 20→}
 21→
 22→export async function validateChatId(token: string, chatId: number): Promise<
 23→  { ok: true; title: string; isForum: boolean } | { ok: false; error: string }
 24→> {
 25→  try {
 26→    const res = await fetch(`https://api.telegram.org/bot${token}/getChat`, {
 27→      method: 'POST',
 28→      headers: { 'Content-Type': 'application/json' },
 29→      body: JSON.stringify({ chat_id: chatId }),
 30→    })
 31→    const data = await res.json() as {
 32→      ok: boolean
 33→      result?: { title: string; type: string; is_forum?: boolean }
 34→      description?: string
 35→    }
 36→    if (!data.ok || !data.result) {
 37→      return { ok: false, error: data.description || 'Invalid chat ID' }
 38→    }
 39→    if (data.result.type !== 'supergroup') {
 40→      return { ok: false, error: `Chat is "${data.result.type}", must be a supergroup` }
 41→    }
 42→    return { ok: true, title: data.result.title, isForum: data.result.is_forum === true }
 43→  } catch (err) {
 44→    return { ok: false, error: (err as Error).message }
 45→  }
 46→}
 47→
 48→// --- Agent detection ---
 49→
 50→const KNOWN_AGENTS: Array<{ name: string; commands: string[] }> = [
 51→  { name: 'claude', commands: ['claude-agent-acp', 'claude', 'claude-code'] },
 52→  { name: 'codex', commands: ['codex'] },
 53→]
 54→
 55→export async function detectAgents(): Promise<Array<{ name: string; command: string }>> {
 56→  const found: Array<{ name: string; command: string }> = []
 57→  for (const agent of KNOWN_AGENTS) {
 58→    for (const cmd of agent.commands) {
 59→      try {
 60→        execFileSync('which', [cmd], { stdio: 'pipe' })
 61→        found.push({ name: agent.name, command: cmd })
 62→        break // found one for this agent, skip alternatives
 63→      } catch {
 64→        // not found, try next
 65→      }
 66→    }
 67→  }
 68→  return found
 69→}
 70→
 71→export async function validateAgentCommand(command: string): Promise<boolean> {
 72→  try {
 73→    execFileSync('which', [command], { stdio: 'pipe' })
 74→    return true
 75→  } catch {
 76→    return false
 77→  }
 78→}
 79→
 80→// --- Setup steps ---
 81→
 82→export async function setupTelegram(): Promise<NonNullable<Config['channels']['telegram']>> {
 83→  console.log('\n--- Step 1: Telegram Setup ---\n')
 84→
 85→  let botToken = ''
 86→  let botUsername = ''
 87→  let botName = ''
 88→
 89→  while (true) {
 90→    botToken = await input({
 91→      message: 'Telegram bot token (from @BotFather):',
 92→      validate: (val) => val.trim().length > 0 || 'Token cannot be empty',
 93→    })
 94→    botToken = botToken.trim()
 95→
 96→    console.log('Validating bot token...')
 97→    const result = await validateBotToken(botToken)
 98→    if (result.ok) {
 99→      botUsername = result.botUsername
100→      botName = result.botName
101→      console.log(`✓ Bot "${botName}" (@${botUsername}) connected`)
102→      break
103→    }
104→    console.log(`✗ Validation failed: ${result.error}`)
105→    const action = await select({
106→      message: 'What would you like to do?',
107→      choices: [
108→        { name: 'Re-enter token', value: 'retry' },
109→        { name: 'Skip validation (use token as-is)', value: 'skip' },
110→      ],
111→    })
112→    if (action === 'skip') break
113→  }
114→
115→  let chatId = 0
116→
117→  while (true) {
118→    const chatIdStr = await input({
119→      message: 'Telegram supergroup chat ID (e.g. -1001234567890):',
120→      validate: (val) => {
121→        const n = Number(val.trim())
122→        if (isNaN(n) || !Number.isInteger(n)) return 'Chat ID must be an integer'
123→        return true
124→      },
