    if (available.length > 0) {
      // Prefer claude-agent-acp over claude/claude-code
      const preferred = available.find(c => c === 'claude-agent-acp') ?? available[0]
      found.push({ name: agent.name, command: preferred })
    }
  }
  return found
}

