async function detectChatId(token: string): Promise<number> {
  // Clear old updates first
  let lastUpdateId = 0;
  try {
    const clearRes = await fetch(
      `https://api.telegram.org/bot${token}/getUpdates?offset=-1`,
    );
    const clearData = (await clearRes.json()) as {
      ok: boolean;
      result?: Array<{ update_id: number }>;
    };
    if (clearData.ok && clearData.result?.length) {
      lastUpdateId =
        clearData.result[clearData.result.length - 1].update_id;
    }
  } catch {
    // ignore
  }

  console.log("\n  1. Add the bot to your Telegram supergroup");
  console.log("  2. Send any message in that group");
  console.log("\n  Waiting for a message... (press Ctrl+C to cancel)\n");

  const MAX_ATTEMPTS = 60; // ~60 seconds
  const POLL_INTERVAL = 1000;

  for (let i = 0; i < MAX_ATTEMPTS; i++) {
    try {
      const offset = lastUpdateId ? lastUpdateId + 1 : 0;
      const res = await fetch(
        `https://api.telegram.org/bot${token}/getUpdates?offset=${offset}&timeout=1`,
      );
      const data = (await res.json()) as {
        ok: boolean;
        result?: Array<{
          update_id: number;
          message?: {
            chat: { id: number; title?: string; type: string };
          };
          my_chat_member?: {
            chat: { id: number; title?: string; type: string };
          };
        }>;
      };

      if (!data.ok || !data.result?.length) {
        await new Promise((r) => setTimeout(r, POLL_INTERVAL));
        continue;
      }

      // Collect unique supergroups from updates
      const groups = new Map<number, string>();
      for (const update of data.result) {
        lastUpdateId = update.update_id;
        const chat =
          update.message?.chat ?? update.my_chat_member?.chat;
        if (chat && (chat.type === "supergroup" || chat.type === "group")) {
          groups.set(chat.id, chat.title ?? String(chat.id));
        }
      }

      if (groups.size === 1) {
        const [id, title] = [...groups.entries()][0];
        console.log(`✓ Detected group: "${title}" (${id})`);
        return id;
      }

      if (groups.size > 1) {
        const choices = [...groups.entries()].map(([id, title]) => ({
          name: `${title} (${id})`,
          value: id,
        }));
        const selected = await select({
          message: "Multiple groups detected. Which one?",
          choices,
        });
        return selected;
      }
    } catch {
      // Network error, retry
    }
    await new Promise((r) => setTimeout(r, POLL_INTERVAL));
  }

  console.log("⚠ Auto-detect timed out. Please enter chat ID manually.");
  const chatIdStr = await input({
    message: "Telegram supergroup chat ID:",
    validate: (val) => {
      const n = Number(val.trim());
      if (isNaN(n) || !Number.isInteger(n))
        return "Chat ID must be an integer";
      return true;
    },
  });

